import logging
import shutil
from .file_putter import FilePutter

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class LocalFilePutter(FilePutter):
    """
    FilePutter interface for Local.
    """

    def put_file(self, source_path, target_path):
        logger.debug(
            "putting {source_path!r} into {target_path!r}".format(
                source_path=source_path,
                target_path=target_path))
        shutil.copy(source_path, target_path)
